import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"47、【困】 坎下兌上","description":"周易口訣義 - 47、【困】 坎下兌上","frontmatter":{"title":"47、【困】 坎下兌上","description":"周易口訣義 - 47、【困】 坎下兌上"},"headers":[],"relativePath":"classics/koujueyi/049.md","filePath":"classics/koujueyi/049.md"}'),r={name:"classics/koujueyi/049.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_47、【困】-坎下兌上" tabindex="-1">47、【困】 坎下兌上 <a class="header-anchor" href="#_47、【困】-坎下兌上" aria-label="Permalink to “47、【困】 坎下兌上”">​</a></h1><p>彖曰：「困」，剛揜也。險以說，困而不失其所，亨，其唯君子乎！「貞大人吉」，以剛中也；「有言不信」，尚口乃窮也。</p><p>象曰：澤無水，困，君子以致命遂志。</p><p>初六：臀困於株木，入於幽谷，三歲不覿。</p><p>象曰：「入於幽谷」，幽不明也。</p><p>九二：困於酒食，朱紱方來，利用亨祀。徵兇無咎。</p><p>象曰：「困於酒食」，中有慶也。</p><p>六三：困於石，據於蒺藜，入於其宮，不見其妻，兇。</p><p>象曰：「據於蒺藜」，乘剛也。「入於其宮，不見其妻」，不祥也。</p><p>九四：來徐徐，困於金車，吝，有終。</p><p>象曰：「來徐徐」，志在下也。雖不當位，有與也。</p><p>九五：劓刖，困於赤紱，乃徐有說，利用祭祀。</p><p>象曰：「劓刖」，志未得也。「乃徐有說」，以中直也。「利用祭祀」，受福也。</p><p>上六：困於葛藟，於臲卼，曰動悔有悔，徵吉。</p><p>象曰：「困於葛藟」，未當也；「動悔有悔」，吉行也。</p><p>解讀</p><p>「困，亨」者，「困」者，窮阨委頓之名，道乖力疲之義。小人遭困，則窮斯濫矣。君子處之，貞節不改，而不失其通之道，困而獲濟，故曰「困，亨」。困而不能得通，小人也。「貞大人吉，無咎」者，處困不濫而能自通，此唯體正修德之人，處困而能保之，然後「吉無咎」也。「有言不信」者，當困之時，欲希濟困，必須修身慎行，立德立誠，而乃巧辭飾言以求其濟，人何以信？轉益困窮也。象曰「澤無水，困」者，水在澤下，澤中萬物枯稿，困之象也。「君子以致命遂志」者，君子守道而處，雖遭困厄之世，而不渝濫以謟世俗。假使致命喪身，固當守節不移，以遂高尚之志，故素書雲「如其不遇，沒身而已」是也。</p><p>「初六，臀困於株木，入於幽谷，三歲不覿」者，以陰爻最居窮下，即是沉滯窮困，居不得安，若處於株木之上，故曰「臀困於株木」也。處困之時，欲進即二隔其路，欲且處，又居之不安，懼於困危，遂乃逃竄，故曰「入於幽谷」也。困極即通，事之常理，不過數年，困危必釋，可以出矣，故曰「三歲不覿」也。</p><p>「九二，困於酒食，朱紱方來，利用亨祀，徵兇，無咎」者，以剛處中，以陽居正，又無偏應，體剛即能濟困，居陰即以謙待物，物之所歸也。處中即德行不邪，無應即心無私黨，有此眾美，即物皆歸己，不勝飽飫，故曰「困於酒食」也。朱紱，南方祭服也。九二體屬坎卦，坎為北方，言九二有此美德，陽明方物而來，即東西二方必至，故曰「朱紱方來」。四方歸向，庶物豐盈，可以亨薦神明，克降其福，故曰「利用亨祀」也。盈而又進，傾敗道也。以此徵行，兇危交至，故「徵兇」。兇禍自己所招，豈合咎怨他人，即得「無咎」也。</p><p>「六三，困於石，據於蒺藜，入於其宮，不見其妻，兇」者，石者，為物堅剛而不可入，謂九四也；蒺藜之草，有刺而不可踐，謂九二也。六三以陰居陽，不正而處，上無應援，無所之適，志懷剛武，欲親於四，四又不受，如石之堅；欲附九二，二又不許，猶如蒺藜，刺而難踐，故曰「困於石，據於蒺藜」也。無應而行，失其配偶，譬之入於宮中而不見其妻，處困如斯，固其兇矣。「九四，來徐徐，困於金車，吝，有終」者，「徐徐」是疑懼不速之貌也；「金車」謂九二以剛處中，如車材強壯也。四欲就初六，懼九二為難，心懷疑懼，不敢速進，是困於九二之金車，故曰「來徐徐，困於金車」也。有應在初，而未相遇，是以有「吝」，以謙得物，故乃「有終」也。</p><p>「九五，劓刖，困於赤紱，乃徐有說，利用祭祀」者，以陽居陽而無謙遜，物則不附，怒其不來附己，乃行劓刖之刑，故異方之人，轉更離叛，故曰「困於赤紱」矣。以剛居中，不昧所見，改修其道，以謙得眾，故用寬徐，人悉歸己，乃有喜悅，故曰「乃徐有說」。剛而處尊，而用中直，即可亨祭而獲福慶，故曰「利用祭祀」也。</p><p>「上六：困於葛藟，於臲卼，曰動悔有悔，徵吉」者，葛，蔓也；藟，纏繞貌。臲卼，搖動不安貌。上六處困之極，即是困極也。無應乘剛，行即被物纏繞，居則臲卼不安，故曰「困於葛藟，於臲卼」也。曰，思謀之辭也。凡物窮思變，極即謀通，處至困之地，何有通路？故須思謀。曰：我若守此，必見不濟，謀逃逸可以免之。發意逃時，其悔乃生，故繫辭雲：「吉凶悔吝生乎動。」是初動而有憂悔，當奔逸冒險之時，又生憂悔，既出險外，即不慮危困，所以徵行而獲吉，故曰「動悔有悔，徵吉」也。</p>',22)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
